// Источник: web-тест .qa/e2e/tests/important-dates/id-02-edit-save-delete.spec.ts, план .qa/e2e/specs/important-dates.md (17.2), кейс .qa/tests/important-dates/ID-02-edit-and-delete-date.md
// Тикет #6a86f7e6. Опора: AC2; реджект 27.09 п.4; ID-02 «Ожидаемо».
// @data: создаёт «QA-AUTO-היום», правит в «QA-AUTO-מחר», удаляет с подтверждением; в finally удаляются ВСЕ «QA-AUTO-…».
// «Сегодня/завтра» — реальные даты устройства (часы не сдвигаем). Reload web = перезапуск приложения.
import { $$, driver, expect } from '@wdio/globals';
import { byLabel, byLabelStartsWith, byText, byTextContains, tapLabel, tapText, expectVisibleText, expectTextContains, swipeUp } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { addDays, dotDate, isoDate } from '../../../e2e/tests/_helpers/dates.ts';

const NOW = new Date();
const TODAY = isoDate(NOW);
const TOMORROW = isoDate(addDays(NOW, 1));
const TOMORROW_DOT = dotDate(addDays(NOW, 1));

const appId = () => (driver.isAndroid ? process.env.APP_ANDROID_PACKAGE : process.env.APP_IOS_BUNDLE) ?? '';
const editButtons = () => (driver.isAndroid
  ? $$('android=new UiSelector().descriptionMatches(".*QA-AUTO-.*: פתיחה לעריכה")').getElements()
  : $$('-ios predicate string:name MATCHES ".*QA-AUTO-.*: פתיחה לעריכה"').getElements());

async function isChecked(label: string) {
  const el = await byLabel(label);
  if (driver.isAndroid) return (await el.getAttribute('checked')) === 'true' || (await el.getAttribute('selected')) === 'true';
  return ['1', 'true'].includes(String(await el.getAttribute('value')));
}
async function fieldValue(label: string) {
  const el = await byLabel(label);
  return driver.isAndroid ? el.getText() : String((await el.getAttribute('value')) ?? '');
}
async function homeDates() {
  await goTab('בית');
  const add = await byLabel('הוספת תאריך חשוב');
  for (let i = 0; i < 8 && !(await add.isDisplayed().catch(() => false)); i++) await swipeUp();
  await add.waitForDisplayed({ timeout: 20000 });
}
async function scrollToLabel(label: string) {
  const el = await byLabel(label);
  for (let i = 0; i < 6 && !(await el.isDisplayed().catch(() => false)); i++) await swipeUp();
  await el.waitForDisplayed({ timeout: 20000 });
  return el;
}
/** Выбрать день; если его нет в текущем месяце — «החודש הבא». */
async function pickDay(iso: string) {
  const day = await byLabelStartsWith(`${iso}, `);
  if (!(await day.isDisplayed().catch(() => false))) await tapLabel('החודש הבא');
  await (await byLabelStartsWith(`${iso}, `)).click();
}
async function deleteQaDates() {
  await toHome();
  await homeDates();
  for (let guard = 0; guard < 10; guard++) {
    const list = await editButtons();
    if (list.length === 0) break;
    await list[0].click();
    await tapText('מחיקת התאריך');
    await tapText('מחיקה');
    await driver.waitUntil(async () => (await editButtons()).length < list.length, { timeout: 15000 });
  }
}

describe('Важные даты и אזכרות', () => {
  afterEach(async () => { await toHome(); });

  it('ID-02 Карандаш → правка (имя, дата, тип) → сохранить → удалить с подтверждением #6a86f7e6 @data', async () => {
    try {
      // 1. «הוספת תאריך חשוב» → «תאריך חשוב» → «QA-AUTO-היום», сегодня → «הוסף תאריך».
      await homeDates();
      await tapLabel('הוספת תאריך חשוב');
      await tapText('תאריך חשוב');
      await (await byLabel('שם התאריך')).setValue('QA-AUTO-היום');
      await pickDay(TODAY);
      await tapText('הוסף תאריך');
      await expect(byLabel('שם התאריך')).not.toBeDisplayed();

      // 2. Карандаш → «עריכת תאריך»: тип, имя, выбранный день, кнопки; имя → «QA-AUTO-מחר», завтра → «שמירת השינויים»; перезапуск.
      await (await scrollToLabel('QA-AUTO-היום: פתיחה לעריכה')).click();
      await expectVisibleText('עריכת תאריך');
      expect(await isChecked('תאריך חשוב')).toBe(true);
      expect(await isChecked('אזכרה')).toBe(false);
      expect(await fieldValue('שם התאריך')).toBe('QA-AUTO-היום');
      const todayRadio = await byLabelStartsWith(`${TODAY}, `);
      expect(driver.isAndroid
        ? (await todayRadio.getAttribute('checked')) === 'true' || (await todayRadio.getAttribute('selected')) === 'true'
        : ['1', 'true'].includes(String(await todayRadio.getAttribute('value')))).toBe(true);
      await expectVisibleText('שמירת השינויים');
      await expectVisibleText('מחיקת התאריך');
      await (await byLabel('שם התאריך')).setValue('QA-AUTO-מחר');
      await pickDay(TOMORROW);
      await tapText('שמירת השינויים');
      await expect(byText('עריכת תאריך')).not.toBeDisplayed();
      await driver.terminateApp(appId());
      await driver.activateApp(appId());
      await (await byText('בית')).waitForDisplayed({ timeout: 30000 });
      await homeDates();
      await scrollToLabel('QA-AUTO-מחר: פתיחה לעריכה');
      await expect(byTextContains('QA-AUTO-היום')).not.toBeDisplayed();
      await expectTextContains(TOMORROW_DOT);

      // 3. Карандаш → тип «אזכרה» (не сохранять): «שם הנפטר», «אחרי השקיעה»; завтрашний день — будущий: ошибка, сохранить нельзя → «סגירה».
      await tapLabel('QA-AUTO-מחר: פתיחה לעריכה');
      await tapLabel('אזכרה');
      await expect(byLabel('שם הנפטר')).toBeDisplayed();
      await expect(byLabel('הפטירה הייתה אחרי השקיעה')).toBeDisplayed();
      await expect(byLabelStartsWith(`${TOMORROW}, `)).toBeDisabled();
      await expectTextContains('תאריך הפטירה לא יכול להיות בעתיד.');
      await expect(byText('שמירת השינויים')).toBeDisabled();
      await tapLabel('סגירה');
      await expect(byText('עריכת תאריך')).not.toBeDisplayed();
      await expect(byLabel('QA-AUTO-מחר: פתיחה לעריכה')).toBeDisplayed();

      // 4. Удаление с подтверждением: текст окна, «ביטול», «מחיקה».
      await tapLabel('QA-AUTO-מחר: פתיחה לעריכה');
      await tapText('מחיקת התאריך');
      await expectVisibleText('למחוק את התאריך?');
      await expectTextContains('«QA-AUTO-מחר» יימחק מהתאריכים החשובים שלך, ואי אפשר יהיה לשחזר אותו.');
      await expectVisibleText('ביטול');
      await tapText('מחיקה');
      await expect(byText('למחוק את התאריך?')).not.toBeDisplayed();
    } finally {
      // Уборка + проверка: нет «QA-AUTO-» на «בית» и в «פרופיל אישי».
      await deleteQaDates();
      await expect(byTextContains('QA-AUTO-')).not.toBeDisplayed();
      await goTab('המסע שלי');
      await tapLabel('מעבר לפרטים שלי');
      await expectVisibleText('פרופיל אישי');
      const section = await byText('תאריכים חשובים');
      for (let i = 0; i < 8 && !(await section.isDisplayed().catch(() => false)); i++) await swipeUp();
      await expect(byTextContains('QA-AUTO-')).not.toBeDisplayed();
    }
  });
});
